/* ============================================================================
   DESARROLLO_PLANIFICADO_2  (28/10/2026)  marca DES_PLAN_V2  -- requiere DESARROLLO_PLANIFICADO_1 aplicado
   ----------------------------------------------------------------------------
   - Trabajo de la visita: avatar del consultor y estado / origen a la derecha en su fila; titulo (2 lineas) y
     desarrollo (3 lineas) recortados con el texto completo al pasar el mouse; "Planificado en esta visita" sin
     fecha en el titulo (cada desarrollo dice para que visita es); lo planificado para una visita que ya llego
     queda "Pendiente de pasar a realizado" en esa visita.
   - No se puede planificar otro desarrollo mientras haya planificados para visitas de hoy o anteriores
     (pasarlos a realizado o eliminarlos). Aviso dentro del modal de desarrollo.
   - Assets: vct-proyecto-v360.css ?v=52 y vct-proyecto-v360.js ?v=44 (subir los dos archivos).
   Si alguno de los puntos no se encuentra, NO se cambia nada. Re-ejecutable.  SSMS: F5.
   ============================================================================ */
USE [MuhlePROD];
SET NOCOUNT ON;
GO
DECLARE @D NVARCHAR(MAX) = OBJECT_DEFINITION(OBJECT_ID('dbo.VCT_MAIN_PROYECTO_V360')), @NE NVARCHAR(MAX), @RE NVARCHAR(MAX), @i INT, @F NVARCHAR(MAX) = N'', @s INT, @p INT;
IF @D IS NULL
    PRINT 'FALLO: no se encontro dbo.VCT_MAIN_PROYECTO_V360.';
ELSE IF CHARINDEX(N'DES_PLAN_V2', @D) > 0
    PRINT 'OK   el parche DES_PLAN_V2 ya estaba aplicado: no se hizo nada.';
ELSE IF CHARINDEX(N'DES_PLAN_V1', @D) = 0
    PRINT 'FALLO: falta aplicar antes DESARROLLO_PLANIFICADO_1.sql. No se cambio nada.';
ELSE
BEGIN
    SET @D = REPLACE(@D, NCHAR(13) + NCHAR(10), NCHAR(10));
    /* val_pend */
    SET @NE = CONVERT(NVARCHAR(MAX), N'') + N'                SET @ERR = ''Un desarrollo planificado va en una visita futura.''' + NCHAR(10);
    SET @RE = CONVERT(NVARCHAR(MAX), N'') + N'                SET @ERR = ''Un desarrollo planificado va en una visita futura.''' + NCHAR(10) + N'            /* DES_PLAN_V2: antes de planificar otro, lo planificado para visitas que ya llegaron se pasa a realizado o se elimina */' + NCHAR(10) + N'            ELSE IF @DS_TIPO = ''PLANIFICADO'' AND NOT EXISTS (SELECT 1 FROM dbo.VCT_ACCIONES_DESARROLLO DX WITH(NOLOCK) WHERE DX.ID = ISNULL(@DS_ID, -1) AND DX.TIPO = ''PLANIFICADO'')' + NCHAR(10) + N'                 AND EXISTS (SELECT 1 FROM dbo.VCT_ACCIONES_DESARROLLO D2 WITH(NOLOCK) INNER JOIN dbo.VCT_PROYECTOS_VISITAS V2 WITH(NOLOCK) ON V2.ID = D2.ID_VISITA WHERE V2.ID_PROYECTO = @ID_PROYECTO AND D2.TIPO = ''PLANIFICADO'' AND CONVERT(DATE, V2.FECHA_DESDE) <= CONVERT(DATE, @HOY))' + NCHAR(10) + N'                SET @ERR = ''Hay desarrollos planificados para visitas de hoy o anteriores: pasalos a realizado o eliminalos antes de planificar otros.''' + NCHAR(10);
    SET @i = CHARINDEX(@NE, @D);
    IF @i = 0 OR CHARINDEX(@NE, @D, @i + 1) > 0 SET @F = @F + N' val_pend'; ELSE SET @D = STUFF(@D, @i, LEN(@NE + N'x') - 1, @RE);
    /* modal_pend */
    SET @NE = CONVERT(NVARCHAR(MAX), N'') + N'data-pv-des-hoy="'' + CONVERT(VARCHAR(10), @HOY, 120) + ''"';
    SET @RE = CONVERT(NVARCHAR(MAX), N'') + N'data-pv-des-hoy="'' + CONVERT(VARCHAR(10), @HOY, 120) + ''" data-pv-des-pend="'' + ISNULL(STUFF((SELECT '','' + CONVERT(VARCHAR(20), D2.ID) + '':'' + CONVERT(VARCHAR(10), V2.FECHA_DESDE, 120) FROM dbo.VCT_ACCIONES_DESARROLLO D2 WITH(NOLOCK) INNER JOIN dbo.VCT_PROYECTOS_VISITAS V2 WITH(NOLOCK) ON V2.ID = D2.ID_VISITA WHERE V2.ID_PROYECTO = @ID_PROYECTO AND D2.TIPO = ''PLANIFICADO'' AND CONVERT(DATE, V2.FECHA_DESDE) <= CONVERT(DATE, @HOY) ORDER BY V2.FECHA_DESDE, D2.ID FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), 1, 1, ''''), '''') + ''"';
    SET @i = CHARINDEX(@NE, @D);
    IF @i = 0 OR CHARINDEX(@NE, @D, @i + 1) > 0 SET @F = @F + N' modal_pend'; ELSE SET @D = STUFF(@D, @i, LEN(@NE + N'x') - 1, @RE);
    /* assets */
    SET @NE = CONVERT(NVARCHAR(MAX), N'') + N'vct-proyecto-v360.css?v=49"><script src="../js/vct-proyecto-v360.js?v=41"';
    SET @RE = CONVERT(NVARCHAR(MAX), N'') + N'vct-proyecto-v360.css?v=52"><script src="../js/vct-proyecto-v360.js?v=44"';
    SET @i = CHARINDEX(@NE, @D);
    IF @i = 0 OR CHARINDEX(@NE, @D, @i + 1) > 0 SET @F = @F + N' assets'; ELSE SET @D = STUFF(@D, @i, LEN(@NE + N'x') - 1, @RE);
    /* agw (bloque: de su inicio a su fin) */
    SET @NE = CONVERT(NVARCHAR(MAX), N'') + N'        /* PL_DES_V5: trabajo de la visita (boceto B)';
    SET @RE = CONVERT(NVARCHAR(MAX), N'') + N'            FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), '''');' + NCHAR(10) + N'        SET @AG_WM';
    SET @i = CHARINDEX(@NE, @D);
    SET @s = CASE WHEN @i > 0 THEN CHARINDEX(@RE, @D, @i) ELSE 0 END;
    IF @i = 0 OR @s = 0 OR CHARINDEX(@NE, @D, @i + 1) > 0 SET @F = @F + N' agw';
    ELSE SET @D = STUFF(@D, @i, @s - @i + LEN(@RE + N'x') - 1, CONVERT(NVARCHAR(MAX), N'') + N'        /* PL_DES_V5: trabajo de la visita (boceto B): indicadores, por consultor, trabajado y lo que queda para la proxima visita */' + NCHAR(10) + N'        /* DES_PLAN_V1 / DES_PLAN_V2: lo planificado en la visita sigue a la vista con su estado; lo planificado para una visita que ya llego queda pendiente */' + NCHAR(10) + N'        SELECT @AGW = ISNULL((' + NCHAR(10) + N'            SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw" data-pv-agw="'' + CONVERT(VARCHAR(20), A.ID) + ''" hidden''' + NCHAR(10) + N'                 + '' data-x="'' + REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(A.INST + CASE WHEN A.CONS_TXT <> '''' THEN '' - '' + A.CONS_TXT ELSE '''' END,''\'',''/''),''"'',''''''''),CHAR(10),'' ''),CHAR(13),'' ''),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''"''' + NCHAR(10) + N'                 + '' data-d1="'' + CONVERT(VARCHAR(10), A.DESDE, 120) + ''" data-d2="'' + CONVERT(VARCHAR(10), A.HASTA, 120) + ''"''' + NCHAR(10) + N'                 + '' data-tit="Visita del '' + CONVERT(VARCHAR(10), A.DESDE, 103) + CASE WHEN A.HASTA > A.DESDE THEN '' al '' + CONVERT(VARCHAR(10), A.HASTA, 103) ELSE '''' END + ''"''' + NCHAR(10) + N'                 + '' data-sub="'' + REPLACE(REPLACE(REPLACE(REPLACE(A.INST + '' - '' + CASE A.SIT WHEN ''e'' THEN ''Ejecutada'' WHEN ''c'' THEN ''Confirmada'' ELSE ''Pendiente'' END + CASE WHEN A.CONS_TXT <> '''' THEN '' - '' + A.CONS_TXT ELSE '''' END,''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-k"><div><small>Horas de la visita</small><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), A.HT)), ''.0'', '''') + '' h</b><em>'' + CONVERT(VARCHAR(10), ISNULL(NC.N, 0)) + '' consultor'' + CASE WHEN ISNULL(NC.N, 0) = 1 THEN '''' ELSE ''es'' END + ''</em></div>''' + NCHAR(10) + N'                 + ''<div><small>Volcadas en desarrollos</small><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(R.H, 0))), ''.0'', '''') + '' h</b><em>'' + CONVERT(VARCHAR(10), CASE WHEN A.HT > 0 THEN CONVERT(INT, ROUND(ISNULL(R.H, 0) * 100.0 / A.HT, 0)) ELSE 0 END) + '' %</em></div>''' + NCHAR(10) + N'                 + ''<div><small>Sin detallar (informe)</small><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), CASE WHEN A.HT > ISNULL(R.H, 0) THEN A.HT - ISNULL(R.H, 0) ELSE 0 END)), ''.0'', '''') + '' h</b></div>''' + NCHAR(10) + N'                 + ''<div><small>Transcurrido desde 1&ordf; visita</small><b>'' + CASE WHEN @F_V1 IS NULL THEN ''-'' ELSE CONVERT(VARCHAR(10), DATEDIFF(DAY, @F_V1, A.DESDE)) + '' d&iacute;as'' END + ''</b>''' + NCHAR(10) + N'                 + CASE WHEN @F_V1 IS NULL THEN '''' ELSE ''<em>desde '' + CONVERT(VARCHAR(5), @F_V1, 103) + ''</em>'' END + ''</div></div>''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-sec">Por consultor</div>''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-tb"><div class="vct-pv-agw-tr is-h"><span>Consultor</span><span>Visita</span><span>Detallado</span><span>Sin detallar</span><span>Uso</span></div>''' + NCHAR(10) + N'                 + ISNULL((SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw-tr"><span><b>'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                                      + CASE WHEN EXISTS (SELECT 1 FROM #EQ Q WHERE Q.TIPO = ''CONSULTOR'' AND Q.ID_ENT = VC.ID_CONSULTOR AND Q.ROL_COD = ''CONSULTOR_LIDER'') THEN ''<i class="vct-pv-agw-lid">L&iacute;der</i>'' ELSE '''' END + ''</span>''' + NCHAR(10) + N'                                      + ''<span>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)))), ''.0'', '''') + '' h</span>''' + NCHAR(10) + N'                                      + ''<span>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(DD.H, 0))), ''.0'', '''') + '' h</span>''' + NCHAR(10) + N'                                      + ''<span>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), CASE WHEN ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)) > ISNULL(DD.H, 0) THEN ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)) - ISNULL(DD.H, 0) ELSE 0 END)), ''.0'', '''') + '' h</span>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-bar"><span class="is-plan" style="width:'' + CONVERT(VARCHAR(10), CASE WHEN ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)) <= 0 THEN 0' + NCHAR(10) + N'                                             WHEN ISNULL(DD.H, 0) >= ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)) THEN 100' + NCHAR(10) + N'                                             ELSE CONVERT(INT, ROUND(ISNULL(DD.H, 0) * 100.0 / ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)), 0)) END) + ''%"></span></span></div>''' + NCHAR(10) + N'                                 FROM dbo.VCT_PROYECTOS_VISITAS_CONSULTORES VC WITH(NOLOCK)' + NCHAR(10) + N'                                 OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = VC.ID_CONSULTOR) Y' + NCHAR(10) + N'                                 OUTER APPLY (SELECT SUM(D.HORAS) AS H FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) WHERE D.ID_VISITA = A.ID AND D.ID_CONSULTOR = VC.ID_CONSULTOR AND D.TIPO = ''REALIZADO'') DD' + NCHAR(10) + N'                                 WHERE VC.ID_VISITA = A.ID ORDER BY Y.NOM' + NCHAR(10) + N'                                 FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), '''') + ''</div>''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-cols">''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-col"><div class="vct-pv-agw-h">&#10003; Trabajado en esta visita<span class="vct-360-badge is-active">'' + CONVERT(VARCHAR(10), ISNULL(R.NR, 0)) + '' desarrollo'' + CASE WHEN ISNULL(R.NR, 0) = 1 THEN '''' ELSE ''s'' END + '' &middot; '' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(R.H, 0))), ''.0'', '''') + '' h</span>''' + NCHAR(10) + N'                 + CASE WHEN A.DESDE <= @HOY AND ISNULL(R.NP, 0) > 0 THEN ''<span class="vct-360-badge is-planned vct-pv-agw-pend">'' + CONVERT(VARCHAR(10), R.NP) + '' pendiente'' + CASE WHEN R.NP = 1 THEN '''' ELSE ''s'' END + ''</span>'' ELSE '''' END + ''</div>''' + NCHAR(10) + N'                 + CASE WHEN A.DESDE <= @HOY THEN ISNULL((SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw-it is-pend"><div class="vct-pv-agw-tx">''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-ix" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN I.CODIGO_ITEM + '' - '' ELSE '''' END + ISNULL(I.TITULO, ''''),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">'' + CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN REPLACE(REPLACE(REPLACE(I.CODIGO_ITEM,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + '' &middot; '' ELSE '''' END + REPLACE(REPLACE(REPLACE(ISNULL(I.TITULO, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>''' + NCHAR(10) + N'                                      + ''<b class="vct-pv-agw-tt" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">'' + REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.DESARROLLO, '''') <> '''' THEN ''<p class="vct-pv-agw-ds" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(LEFT(D.DESARROLLO, 1500),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">'' + REPLACE(REPLACE(REPLACE(LEFT(D.DESARROLLO, 1500),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</p>'' ELSE '''' END' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.PROXIMO_PASO, '''') <> '''' THEN ''<em class="vct-pv-agw-nx" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">Pr&oacute;ximo: '' + REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</em>'' ELSE '''' END' + NCHAR(10) + N'                                      + ''<div class="vct-pv-agw-ft"><span class="vct-pv-agw-who"><span class="vctdg-avatar is-c" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">'' + ISNULL(Y.INI, '''') + ''</span>'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>''' + NCHAR(10) + N'                                      + ''<span class="vct-pl-tp is-pe vct-pv-agw-st">Pendiente de pasar a realizado</span>'' + ''</div></div>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-hs">'' + ''&ndash;'' + ''</span></div>''' + NCHAR(10) + N'                                 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'                                 INNER JOIN dbo.VCT_ACCIONES AC WITH(NOLOCK) ON AC.ID = D.ID_ACCION' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS I WITH(NOLOCK) ON I.ID = AC.ID_PLAN_ITEM' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_VISITAS VD WITH(NOLOCK) ON VD.ID = D.ID_VISITA' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_VISITAS VP WITH(NOLOCK) ON VP.ID = D.ID_VISITA_PLAN' + NCHAR(10) + N'                                 OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM, UPPER(LEFT(LTRIM(ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),'''')),1) + LEFT(LTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''')),1)) AS INI FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = D.ID_CONSULTOR) Y' + NCHAR(10) + N'                                 WHERE D.ID_VISITA = A.ID AND D.TIPO = ''PLANIFICADO'' ORDER BY I.ORDEN, D.ID' + NCHAR(10) + N'                                 FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), '''') ELSE '''' END' + NCHAR(10) + N'                 + ISNULL(NULLIF(ISNULL((SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw-it"><div class="vct-pv-agw-tx">''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-ix" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN I.CODIGO_ITEM + '' - '' ELSE '''' END + ISNULL(I.TITULO, ''''),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">'' + CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN REPLACE(REPLACE(REPLACE(I.CODIGO_ITEM,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + '' &middot; '' ELSE '''' END + REPLACE(REPLACE(REPLACE(ISNULL(I.TITULO, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>''' + NCHAR(10) + N'                                      + ''<b class="vct-pv-agw-tt" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">'' + REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.DESARROLLO, '''') <> '''' THEN ''<p class="vct-pv-agw-ds" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(LEFT(D.DESARROLLO, 1500),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">'' + REPLACE(REPLACE(REPLACE(LEFT(D.DESARROLLO, 1500),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</p>'' ELSE '''' END' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.PROXIMO_PASO, '''') <> '''' THEN ''<em class="vct-pv-agw-nx" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">Pr&oacute;ximo: '' + REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</em>'' ELSE '''' END' + NCHAR(10) + N'                                      + ''<div class="vct-pv-agw-ft"><span class="vct-pv-agw-who"><span class="vctdg-avatar is-c" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">'' + ISNULL(Y.INI, '''') + ''</span>'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>''' + NCHAR(10) + N'                                      + CASE WHEN D.FECHA_PLAN IS NOT NULL THEN ''<span class="vct-pl-tp is-pl vct-pv-agw-st">Planificado el '' + CONVERT(VARCHAR(5), ISNULL(VP.FECHA_DESDE, D.FECHA_PLAN), 103) + ''</span>'' ELSE '''' END + ''</div></div>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-hs">'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(D.HORAS, 0))), ''.0'', '''') + '' h'' + ''</span></div>''' + NCHAR(10) + N'                                 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'                                 INNER JOIN dbo.VCT_ACCIONES AC WITH(NOLOCK) ON AC.ID = D.ID_ACCION' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS I WITH(NOLOCK) ON I.ID = AC.ID_PLAN_ITEM' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_VISITAS VD WITH(NOLOCK) ON VD.ID = D.ID_VISITA' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_VISITAS VP WITH(NOLOCK) ON VP.ID = D.ID_VISITA_PLAN' + NCHAR(10) + N'                                 OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM, UPPER(LEFT(LTRIM(ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),'''')),1) + LEFT(LTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''')),1)) AS INI FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = D.ID_CONSULTOR) Y' + NCHAR(10) + N'                                 WHERE D.ID_VISITA = A.ID AND D.TIPO = ''REALIZADO'' ORDER BY I.ORDEN, D.ID' + NCHAR(10) + N'                                 FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), ''''), ''''),' + NCHAR(10) + N'                          CASE WHEN A.DESDE <= @HOY AND ISNULL(R.NP, 0) > 0 THEN '''' ELSE ''<div class="vct-plt-empty">Sin desarrollos realizados en esta visita.</div>'' END)' + NCHAR(10) + N'                 + ''</div>''' + NCHAR(10) + N'                 + CASE WHEN A.DESDE > @HOY' + NCHAR(10) + N'                        THEN ''<div class="vct-pv-agw-col"><div class="vct-pv-agw-h">Planificado para esta visita<span class="vct-360-badge is-planned">'' + CONVERT(VARCHAR(10), ISNULL(R.NP, 0)) + ''</span></div>''' + NCHAR(10) + N'                           + ISNULL(NULLIF(ISNULL((SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw-it"><div class="vct-pv-agw-tx">''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-ix" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN I.CODIGO_ITEM + '' - '' ELSE '''' END + ISNULL(I.TITULO, ''''),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">'' + CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN REPLACE(REPLACE(REPLACE(I.CODIGO_ITEM,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + '' &middot; '' ELSE '''' END + REPLACE(REPLACE(REPLACE(ISNULL(I.TITULO, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>''' + NCHAR(10) + N'                                      + ''<b class="vct-pv-agw-tt" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">'' + REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.DESARROLLO, '''') <> '''' THEN ''<p class="vct-pv-agw-ds" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(LEFT(D.DESARROLLO, 1500),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">'' + REPLACE(REPLACE(REPLACE(LEFT(D.DESARROLLO, 1500),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</p>'' ELSE '''' END' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.PROXIMO_PASO, '''') <> '''' THEN ''<em class="vct-pv-agw-nx" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">Pr&oacute;ximo: '' + REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</em>'' ELSE '''' END' + NCHAR(10) + N'                                      + ''<div class="vct-pv-agw-ft"><span class="vct-pv-agw-who"><span class="vctdg-avatar is-c" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">'' + ISNULL(Y.INI, '''') + ''</span>'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>''' + NCHAR(10) + N'                                      + CASE WHEN D.FECHA_PLAN IS NOT NULL THEN ''<span class="vct-pl-tp is-pl vct-pv-agw-st">Planificado el '' + CONVERT(VARCHAR(5), ISNULL(VP.FECHA_DESDE, D.FECHA_PLAN), 103) + ''</span>'' ELSE '''' END + ''</div></div>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-hs">'' + ''&ndash;'' + ''</span></div>''' + NCHAR(10) + N'                                 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'                                 INNER JOIN dbo.VCT_ACCIONES AC WITH(NOLOCK) ON AC.ID = D.ID_ACCION' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS I WITH(NOLOCK) ON I.ID = AC.ID_PLAN_ITEM' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_VISITAS VD WITH(NOLOCK) ON VD.ID = D.ID_VISITA' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_VISITAS VP WITH(NOLOCK) ON VP.ID = D.ID_VISITA_PLAN' + NCHAR(10) + N'                                 OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM, UPPER(LEFT(LTRIM(ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),'''')),1) + LEFT(LTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''')),1)) AS INI FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = D.ID_CONSULTOR) Y' + NCHAR(10) + N'                                 WHERE D.ID_VISITA = A.ID AND D.TIPO = ''PLANIFICADO'' ORDER BY I.ORDEN, D.ID' + NCHAR(10) + N'                                 FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), ''''), ''''), ''<div class="vct-plt-empty">Nada planificado para esta visita.</div>'')' + NCHAR(10) + N'                           + ''</div>''' + NCHAR(10) + N'                        ELSE ''<div class="vct-pv-agw-col"><div class="vct-pv-agw-h">&rarr; Planificado en esta visita''' + NCHAR(10) + N'                           + ''<span class="vct-360-badge is-planned">'' + CONVERT(VARCHAR(10), ISNULL(PL.N, 0)) + CASE WHEN ISNULL(PL.NR, 0) > 0 THEN '' &middot; '' + CONVERT(VARCHAR(10), PL.NR) + '' realizado'' + CASE WHEN PL.NR = 1 THEN '''' ELSE ''s'' END ELSE '''' END + ''</span></div>''' + NCHAR(10) + N'                           + ISNULL(NULLIF(ISNULL((SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw-it"><div class="vct-pv-agw-tx">''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-ix" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN I.CODIGO_ITEM + '' - '' ELSE '''' END + ISNULL(I.TITULO, ''''),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">'' + CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN REPLACE(REPLACE(REPLACE(I.CODIGO_ITEM,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + '' &middot; '' ELSE '''' END + REPLACE(REPLACE(REPLACE(ISNULL(I.TITULO, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>''' + NCHAR(10) + N'                                      + ''<b class="vct-pv-agw-tt" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">'' + REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.DESARROLLO, '''') <> '''' THEN ''<p class="vct-pv-agw-ds" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(LEFT(D.DESARROLLO, 1500),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">'' + REPLACE(REPLACE(REPLACE(LEFT(D.DESARROLLO, 1500),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</p>'' ELSE '''' END' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.PROXIMO_PASO, '''') <> '''' THEN ''<em class="vct-pv-agw-nx" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">Pr&oacute;ximo: '' + REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</em>'' ELSE '''' END' + NCHAR(10) + N'                                      + ''<div class="vct-pv-agw-ft"><span class="vct-pv-agw-who"><span class="vctdg-avatar is-c" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">'' + ISNULL(Y.INI, '''') + ''</span>'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>''' + NCHAR(10) + N'                                      + CASE WHEN D.TIPO = ''REALIZADO'' THEN ''<span class="vct-pl-tp is-re vct-pv-agw-st">Realizado el '' + CONVERT(VARCHAR(5), VD.FECHA_DESDE, 103) + ''</span>'' WHEN CONVERT(DATE, VD.FECHA_DESDE) <= CONVERT(DATE, @HOY) THEN ''<span class="vct-pl-tp is-pe vct-pv-agw-st">Pendiente &middot; visita '' + CONVERT(VARCHAR(5), VD.FECHA_DESDE, 103) + ''</span>'' ELSE ''<span class="vct-pl-tp is-pl vct-pv-agw-st">Para la visita '' + CONVERT(VARCHAR(5), VD.FECHA_DESDE, 103) + ''</span>'' END + ''</div></div>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-hs">'' + CASE WHEN D.TIPO = ''REALIZADO'' THEN REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(D.HORAS, 0))), ''.0'', '''') + '' h'' ELSE ''&ndash;'' END + ''</span></div>''' + NCHAR(10) + N'                                 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'                                 INNER JOIN dbo.VCT_ACCIONES AC WITH(NOLOCK) ON AC.ID = D.ID_ACCION' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS I WITH(NOLOCK) ON I.ID = AC.ID_PLAN_ITEM' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_VISITAS VD WITH(NOLOCK) ON VD.ID = D.ID_VISITA' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_VISITAS VP WITH(NOLOCK) ON VP.ID = D.ID_VISITA_PLAN' + NCHAR(10) + N'                                 OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM, UPPER(LEFT(LTRIM(ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),'''')),1) + LEFT(LTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''')),1)) AS INI FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = D.ID_CONSULTOR) Y' + NCHAR(10) + N'                                 WHERE D.ID_VISITA_PLAN = A.ID ORDER BY VD.FECHA_DESDE, I.ORDEN, D.ID' + NCHAR(10) + N'                                 FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), '''')' + NCHAR(10) + N'                                    + ISNULL((SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw-it is-paso"><div>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-ix">'' + CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN REPLACE(REPLACE(REPLACE(I.CODIGO_ITEM,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + '' &middot; '' ELSE '''' END + REPLACE(REPLACE(REPLACE(ISNULL(I.TITULO, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>''' + NCHAR(10) + N'                                      + ''<b>'' + REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-who">'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + '' &middot; pr&oacute;ximo paso de esta visita</span></div><span class="vct-pv-agw-hs">&ndash;</span></div>''' + NCHAR(10) + N'                                 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'                                 INNER JOIN dbo.VCT_ACCIONES AC WITH(NOLOCK) ON AC.ID = D.ID_ACCION' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS I WITH(NOLOCK) ON I.ID = AC.ID_PLAN_ITEM' + NCHAR(10) + N'                                 OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = D.ID_CONSULTOR) Y' + NCHAR(10) + N'                                 WHERE D.ID_VISITA = A.ID AND D.TIPO = ''REALIZADO'' AND ISNULL(D.PROXIMO_PASO, '''') <> '''' ORDER BY I.ORDEN, D.ID' + NCHAR(10) + N'                                 FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), ''''), ''''),' + NCHAR(10) + N'                                    ''<div class="vct-plt-empty">Nada planificado en esta visita.</div>'')' + NCHAR(10) + N'                           + ''</div>'' END' + NCHAR(10) + N'                 + ''</div></div>''' + NCHAR(10) + N'            FROM #AGV A' + NCHAR(10) + N'            OUTER APPLY (SELECT SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN ISNULL(D.HORAS, 0) ELSE 0 END) AS H,' + NCHAR(10) + N'                                SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN 1 ELSE 0 END) AS NR,' + NCHAR(10) + N'                                SUM(CASE WHEN D.TIPO = ''PLANIFICADO'' THEN 1 ELSE 0 END) AS NP' + NCHAR(10) + N'                         FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) WHERE D.ID_VISITA = A.ID) R' + NCHAR(10) + N'            OUTER APPLY (SELECT COUNT(*) AS N FROM dbo.VCT_PROYECTOS_VISITAS_CONSULTORES VC WITH(NOLOCK) WHERE VC.ID_VISITA = A.ID) NC' + NCHAR(10) + N'            OUTER APPLY (SELECT COUNT(*) AS N, SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN 1 ELSE 0 END) AS NR FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) WHERE D.ID_VISITA_PLAN = A.ID) PL' + NCHAR(10) + N'            ORDER BY A.DESDE, A.ID' + NCHAR(10) + N'            FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), '''');' + NCHAR(10) + N'        SET @AG_WM');
    IF @F <> N''
        PRINT 'FALLO: no se encontraron (o estan repetidos) en la definicion vigente los puntos:' + @F + '. No se cambio nada.';
    ELSE
    BEGIN
        SET @s = CHARINDEX(N'PROCEDURE', @D);
        SET @p = CASE WHEN @s > 40 THEN @s - 40 ELSE 1 END;
        IF CHARINDEX(N'CREATE', SUBSTRING(@D, @p, 40)) > 0 AND CHARINDEX(N'OR ALTER', SUBSTRING(@D, @p, 40)) = 0
            SET @D = STUFF(@D, @p + CHARINDEX(N'CREATE', SUBSTRING(@D, @p, 40)) - 1, 6, N'ALTER ');
        BEGIN TRY
            EXEC sys.sp_executesql @D;
            PRINT 'OK   VCT_MAIN_PROYECTO_V360 actualizado (DES_PLAN_V2). Subir vct-proyecto-v360.css (v52) y vct-proyecto-v360.js (v44).';
        END TRY
        BEGIN CATCH
            PRINT 'FALLO al actualizar dbo.VCT_MAIN_PROYECTO_V360 (no se cambio): ' + ERROR_MESSAGE() + ' (linea ' + CONVERT(VARCHAR(10), ERROR_LINE()) + ')';
        END CATCH;
    END;
END;
